cd /tmp/sv-162bb18a05ff41668e7f9f3b9b789c1d/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {(project_basename, framework, package_id): resolved_version}
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                lookup[(name, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for key in all_keys:
    proj, fw, pkg = key
    bv = b.get(key)
    av = a.get(key)
    if bv is None:
        changes.append((proj, fw, pkg, '-', av, 'Added'))
    elif av is None:
        changes.append((proj, fw, pkg, bv, '-', 'Removed'))
    elif bv != av:
        changes.append((proj, fw, pkg, bv, av, 'Aligned to highest version'))
    else:
        unchanged.append((proj, fw, pkg, av))

if changes:
    print('CHANGES:')
    print(f'{\"Project\":<16} {\"Framework\":<10} {\"Package\":<48} {\"Before\":<12} {\"After\":<12} Status')
    print('-' * 120)
    for c in changes:
        print(f'{c[0]:<16} {c[1]:<10} {c[2]:<48} {c[3]:<12} {c[4]:<12} {c[5]}')
    print()

print('UNCHANGED:')
print(f'{\"Project\":<16} {\"Framework\":<10} {\"Package\":<48} {\"Version\":<12}')
print('-' * 90)
for u in unchanged:
    print(f'{u[0]:<16} {u[1]:<10} {u[2]:<48} {u[3]:<12}')
"

